using System;using System.IO;using System.Text;using System.Collections.Generic;using System.Drawing;using ScoreModern.RecoveredFragments;
namespace ScoreModern {
 public static class NativeCode9Terms {
  sealed class Resource {public long Modified,Length;public Dictionary<int,string> Entries;}
  static readonly Dictionary<string,Resource> cache=new Dictionary<string,Resource>(StringComparer.OrdinalIgnoreCase);
  internal static string ResourceKey(string root){var parts=new List<string>();foreach(string name in new[]{"CODE9.DAT","GUITAR.DAT"}){string path=NativeLibraryLocation.FileFor(root,name);var file=new FileInfo(path);parts.Add(file.FullName+"|"+(file.Exists?file.LastWriteTimeUtc.Ticks+":"+file.Length:"missing"));}return String.Join("|",parts);}
  public static bool IsTerm(int number){return number>=3000&&number<=3069;}
  public static Dictionary<int,string> Read(string root){string path=NativeLibraryLocation.FileFor(root,"CODE9.DAT");var info=new FileInfo(path);if(!info.Exists)throw new FileNotFoundException("CODE9 text library not found.",path);Resource saved;if(cache.TryGetValue(info.FullName,out saved)&&saved.Modified==info.LastWriteTimeUtc.Ticks&&saved.Length==info.Length)return new Dictionary<int,string>(saved.Entries);var entries=new Dictionary<int,string>();int lineNumber=0,total=0;foreach(string source in File.ReadAllLines(path,Encoding.GetEncoding(437))){lineNumber++;if(String.IsNullOrWhiteSpace(source)||source.StartsWith("%",StringComparison.Ordinal))continue;int number;if(source.Length<8||source[4]!=' '||!Int32.TryParse(source.Substring(0,4),out number)||!IsTerm(number))throw new InvalidDataException("Invalid CODE9.DAT entry at line "+lineNumber+"; expected3000–3069, one space and a SCORE text/font string.");string value=source.Substring(5).TrimEnd(' ','\t');if(value.Length<3||value[0]!='_'||value[1]<'0'||value[1]>'9'||value[2]<'0'||value[2]>'9')throw new InvalidDataException("CODE9.DAT entry "+number+" needs its three-character SCORE font prefix.");if(entries.ContainsKey(number))throw new InvalidDataException("Duplicate CODE9.DAT number "+number+".");total+=value.Length;if(entries.Count>=70||total>700)throw new NotSupportedException("CODE9.DAT exceeds SCORE's70-entry/700-byte text bank.");entries.Add(number,value);}cache[info.FullName]=new Resource{Modified=info.LastWriteTimeUtc.Ticks,Length=info.Length,Entries=entries};return new Dictionary<int,string>(entries);}
  // CODE9 keeps a cached integer font word separate from the rewritten REAL4
  // parameters. T905 delegate captures: nonzero signed P11 replaces cached P8,
  // while floating P10/P11 are cleared. Both representations matter here.
  public static Item Body(Item source,NativeNotationContext page,ScoreText text,out NativeNotationContext context){string value;int number=(int)source.P(5);if(!IsTerm(number)||!Read(text.RootDirectory).TryGetValue(number,out value))throw new NotSupportedException("No CODE9.DAT text entry for library number "+number+".");float h=(float)(source.P(6)%100);if(h==0)h=1;float v=source.P(7)==0?h:source.P(7);float size=1.0499999523162842f,spacing=source.P(16)==0?size:source.P(16);var body=Item.Make(16,source.P(2),source.P(3),source.P(4),spacing,(float)((double)h*size),(float)((double)v*size),(short)(int)source.P(11)!=0?(short)(int)source.P(11):source.P(8),source.P(9),0,0,1,0);context=new NativeNotationContext{SourceScore=page.SourceScore,Staff=page.Staff,RawBase=page.RawBase,StaffBases=page.StaffBases,Prepared=page.Prepared,Projection=page.Projection};context.Prepared.X=(float)((double)page.Prepared.X+source.P(15)*150);text.Set(body,value,page.Scale);return body;}
  public static bool Draw(Graphics graphics,Item source,NativeNotationContext page,ScoreText text){RenderResourceAudit.Record("CODE9 text term",((int)source.P(5)).ToString(),NativeLibraryLocation.FileFor(text.RootDirectory,"CODE9.DAT"),"external term through recovered SCORE text layout");NativeNotationContext context;var body=Body(source,page,text,out context);text.Draw(graphics,body,body.Text,0,0,page.Scale/5,page.Scale,context);return true;}
  public static List<PrimitiveTextPoint> Scan(Item source,NativeNotationContext page,ScoreText text,short previousFont,out short finalFont){NativeNotationContext context;var body=Body(source,page,text,out context);return text.ScanStrokeText(body,body.Text,context,previousFont,out finalFont);}
 }
}
